def shortest_path(graph, source, target):
    # Check if the source and target are the same node
    if source == target:
        return (0, [source])

    # Initialize BFS queues for both directions
    queue_source = deque([source])
    queue_target = deque([target])
    distance_source_to_target = {source: 0}
    distance_target_to_source = {target: 0}
    visited_source = {source}
    visited_target = {target}

