        if queue_source:
            u = queue_source.popleft()
            for v, w in graph.get(u, []):
                if v not in visited_source:
                    visited_source.add(v)
                    distance_source_to_target[v] = distance_source_to_target[u] + w
                    if v in distance_target_to_source:
                        return (distance_source_to_target[v] + distance_target_to_source[v], path(source, target, distance_source_to_target, distance_target_to_source))
                    queue_source.append(v)

        if queue_target:
            v = queue_target.popleft()
            for u, w in graph.get(v, []):
                if u not in visited_target:
                    visited_target.add(u)
                    distance_target_to_source[u] = distance_target_to_source[v] + w
                    if u in distance_source_to_target:
                        return (distance_source_to_target[u] + distance_target_to_source[u], path(source, target, distance_source_to_target, distance_target_to_source))
                    queue_target.append(u)

    # If no path is found
    return (float("inf"), None)

def path(source, target, distance_source_to_target, distance_target_to_source):
    distances = []
    current_node = target
    while current_node != source:
        path_node = min([current_node, source], key=lambda node: distance_source_to_target[node] + distance_target_to_source[node])
        distances.append(path_node)
        current_node = path_node
    distances.append(source)
    distances.reverse()
    return distances

